// Property schema for elicitation form fields.
//
// Each variant corresponds to a JSON Schema `"type"` value.
// Single-select enums use the `String` variant with `enum` or `oneOf` set.
// Multi-select enums use the `Array` variant.
type ElicitationPropertySchema struct {
	// Type is the "type" tag; it picks the variant that is set.
	Type    string
	String  *StringPropertySchema
	Number  *NumberPropertySchema
	Integer *IntegerPropertySchema
	Boolean *BooleanPropertySchema
	Array   *MultiSelectPropertySchema
}

func (u ElicitationPropertySchema) MarshalJSON() ([]byte, error) {
	var v any = struct{}{}
	switch u.Type {
	case "string":
		if u.String != nil {
			v = u.String
		}
	case "number":
		if u.Number != nil {
			v = u.Number
		}
	case "integer":
		if u.Integer != nil {
			v = u.Integer
		}
	case "boolean":
		if u.Boolean != nil {
			v = u.Boolean
		}
	case "array":
		if u.Array != nil {
			v = u.Array
		}
	}
	return marshalTagged("type", u.Type, v)
}

func (u *ElicitationPropertySchema) UnmarshalJSON(b []byte) error {
	var t struct {
		T string `json:"type"`
	}
	if err := json.Unmarshal(b, &t); err != nil {
		return err
	}
	*u = ElicitationPropertySchema{Type: t.T}
	switch t.T {
	case "string":
		u.String = new(StringPropertySchema)
		return json.Unmarshal(b, u.String)
	case "number":
		u.Number = new(NumberPropertySchema)
		return json.Unmarshal(b, u.Number)
	case "integer":
		u.Integer = new(IntegerPropertySchema)
		return json.Unmarshal(b, u.Integer)
	case "boolean":
		u.Boolean = new(BooleanPropertySchema)
		return json.Unmarshal(b, u.Boolean)
	case "array":
		u.Array = new(MultiSelectPropertySchema)
		return json.Unmarshal(b, u.Array)
	}
	return nil
}

